class CatalogCache:
    def __init__(self, catalog):
        self.catalog = catalog
        self.entries = {}
        self.versions = {}

    def get(self, id):
        # Check if we have a cached entry and if it's still valid
        current_version = self.catalog.versions.get(id)
        if id in self.entries and self.versions.get(id) == current_version:
            return self.entries[id]

        # Fresh read needed - either never cached or cache invalidated  
        self.entries[id] = self.catalog.read(id)
        self.versions[id] = current_version
        return self.entries[id]

